<?php
/** Executive Q&A history. PHP 5.6 compatible. */
use App\Core\Auth;
use App\Core\Db;
use App\Services\AiExecutiveQaService;

if (!Auth::check()||!(Auth::isDevelopmentDepartment()||Auth::canManageEmployees())) { http_response_code(403); echo '<div style="padding:16px;border:1px solid #fecaca;border-radius:14px;background:#fef2f2;color:#b91c1c;font-weight:800;">'.h('접근 권한이 없습니다.').'</div>'; return; }
require_once __DIR__ . '/../../services/AiExecutiveQaService.php';
$qhPdo=null; $qhFailed=false; try { $qhPdo=Db::pdo(); } catch (Exception $e) { $qhFailed=true; error_log('[AI Executive QA History] db failed'); }
$qhFilters=array('analysis_date'=>isset($_GET['analysis_date'])?trim((string)$_GET['analysis_date']):'','target_ym'=>isset($_GET['target_ym'])?trim((string)$_GET['target_ym']):'','answer_status'=>isset($_GET['answer_status'])?trim((string)$_GET['answer_status']):'');
$qhPage=isset($_GET['page'])?max(1,(int)$_GET['page']):1; $qhPerPage=50; $qhStatus=array('installed'=>false); $qhOptions=array('dates'=>array(),'months'=>array()); $qhRows=array(); $qhTotal=0;
if (!$qhFailed&&$qhPdo) { try { $qhStatus=AiExecutiveQaService::schemaStatus($qhPdo); if(!empty($qhStatus['installed'])){$qhOptions=AiExecutiveQaService::historyOptions($qhPdo);$qhTotal=AiExecutiveQaService::countHistory($qhPdo,$qhFilters);} } catch(Exception $e){$qhFailed=true;error_log('[AI Executive QA History] load failed');} }
$qhPages=max(1,(int)ceil($qhTotal/$qhPerPage)); if($qhPage>$qhPages)$qhPage=$qhPages;
if (!$qhFailed&&$qhPdo&&!empty($qhStatus['installed'])) { try { $qhRows=AiExecutiveQaService::listHistory($qhPdo,$qhFilters,$qhPage,$qhPerPage); } catch(Exception $e){$qhFailed=true;error_log('[AI Executive QA History] list failed');} }
if (!function_exists('cpms_qh_url')) { function cpms_qh_url($page,$filters){$params=array('r'=>'admin/ai_executive_qa_history','page'=>$page);foreach($filters as $key=>$value)if($value!=='')$params[$key]=$value;return '?'.http_build_query($params,'','&');} }
?>
<style>.qh-wrap{color:#0f172a}.qh-wrap *{box-sizing:border-box}.qh-hero,.qh-card{border:1px solid #e2e8f0;border-radius:18px;background:#fff;box-shadow:0 8px 26px rgba(15,23,42,.05)}.qh-hero{padding:24px;background:linear-gradient(135deg,#fff,#eef2ff)}.qh-hero h2{margin:0;font-size:27px;font-weight:900}.qh-hero p{color:#475569;line-height:1.7}.qh-links{display:flex;gap:8px;flex-wrap:wrap}.qh-btn{display:inline-flex;padding:10px 14px;border:1px solid #cbd5e1;border-radius:10px;background:#fff;color:#334155;text-decoration:none;font-weight:900}.qh-card{padding:18px;margin-top:14px}.qh-filter{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.qh-filter input,.qh-filter select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:9px}.qh-scroll{overflow-x:auto}.qh-table{width:100%;min-width:1050px;border-collapse:collapse}.qh-table th,.qh-table td{padding:10px;border:1px solid #e2e8f0;text-align:left;vertical-align:top}.qh-table th{background:#f8fafc;color:#475569;font-size:12px}.qh-message{margin-top:14px;padding:14px;border-radius:12px;background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.qh-details{max-width:700px;white-space:normal}.qh-evidence{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:9px}.qh-evidence div{padding:9px;border:1px solid #e2e8f0;border-radius:9px;background:#fff}.qh-pages{display:flex;gap:8px;align-items:center;margin-top:12px}@media(max-width:700px){.qh-filter{grid-template-columns:1fr}.qh-links,.qh-links .qh-btn{width:100%}.qh-evidence{grid-template-columns:1fr}}</style>
<div class="qh-wrap"><section class="qh-hero"><h2>대표 질문·답변 이력</h2><p>저장된 CEO Index와 경영예측 자료를 기준으로 생성된 관리자용 질문·답변 이력입니다. 원본 API 응답과 개인정보는 표시하지 않습니다.</p><div class="qh-links"><a class="qh-btn" href="?r=admin%2Fai_ceo_index">CEO Index</a><a class="qh-btn" href="?r=admin%2Fai_openai_setup">OpenAI 연결 설정</a></div></section>
<?php if($qhFailed): ?><div class="qh-message">대표 질문 이력을 불러오지 못했습니다.</div><?php elseif(!$qhPdo): ?><div class="qh-message">DB 연결 상태를 확인할 수 없습니다.</div><?php elseif(empty($qhStatus['installed'])): ?><div class="qh-message">대표 질문·답변 이력 테이블이 아직 설치되지 않았습니다.</div><?php endif; ?>
<section class="qh-card"><form method="get"><input type="hidden" name="r" value="admin/ai_executive_qa_history"><div class="qh-filter"><label>질문일<select name="analysis_date"><option value="">전체</option><?php foreach($qhOptions['dates'] as $value): ?><option value="<?php echo h($value); ?>"<?php echo $qhFilters['analysis_date']===$value?' selected':''; ?>><?php echo h($value); ?></option><?php endforeach; ?></select></label><label>대상 월<select name="target_ym"><option value="">전체</option><?php foreach($qhOptions['months'] as $value): ?><option value="<?php echo h($value); ?>"<?php echo $qhFilters['target_ym']===$value?' selected':''; ?>><?php echo h($value); ?></option><?php endforeach; ?></select></label><label>답변상태<select name="answer_status"><option value="">전체</option><?php foreach(array('ANSWERED','LIMITED','NOT_AVAILABLE','FAILED','REFUSED') as $value): ?><option value="<?php echo h($value); ?>"<?php echo $qhFilters['answer_status']===$value?' selected':''; ?>><?php echo h($value); ?></option><?php endforeach; ?></select></label><label>&nbsp;<button class="qh-btn" type="submit">조회</button></label></div></form></section>
<section class="qh-card"><strong>전체 <?php echo h(number_format($qhTotal)); ?>건</strong><div class="qh-scroll"><table class="qh-table"><thead><tr><th>질문일시</th><th>질문자</th><th>대상 월</th><th>질문</th><th>답변상태</th><th>사용 모델</th><th>근거자료·답변</th></tr></thead><tbody><?php if(count($qhRows)===0): ?><tr><td colspan="7">표시할 질문·답변 이력이 없습니다.</td></tr><?php else: foreach($qhRows as $row): $points=AiExecutiveQaService::decodeData(isset($row['answer_points_data'])?$row['answer_points_data']:'');$projects=AiExecutiveQaService::decodeData(isset($row['referenced_projects_data'])?$row['referenced_projects_data']:'');$checks=AiExecutiveQaService::decodeData(isset($row['recommended_checks_data'])?$row['recommended_checks_data']:'');$limits=AiExecutiveQaService::decodeData(isset($row['data_limitations_data'])?$row['data_limitations_data']:'');$evidence=AiExecutiveQaService::evidenceCards($row,$qhPdo); ?><tr><td><?php echo h($row['created_at']); ?></td><td><?php echo h(trim((string)$row['actor_name'])!==''?$row['actor_name']:'시스템'); ?></td><td><?php echo h($row['target_ym']); ?></td><td><?php echo h($row['question_text']); ?></td><td><?php echo h($row['answer_status']); ?></td><td><?php echo h($row['model_name']); ?></td><td><details class="qh-details"><summary>상세 보기</summary><?php if(trim((string)$row['answer_summary'])!==''): ?><p><strong><?php echo h($row['answer_summary']); ?></strong></p><?php endif; ?><?php if(count($points)>0): ?><h4>답변 요점</h4><ul><?php foreach($points as $point): ?><li><?php echo h(isset($point['text'])?$point['text']:''); ?></li><?php endforeach; ?></ul><?php endif; ?><?php if(count($projects)>0): ?><h4>언급 현장</h4><ul><?php foreach($projects as $project): ?><li><?php echo h(isset($project['project_name'])?$project['project_name']:'-'); ?></li><?php endforeach; ?></ul><?php endif; ?><?php if(count($evidence)>0): ?><h4>PHP 원본 근거</h4><div class="qh-evidence"><?php foreach($evidence as $metric): ?><div><?php echo h(isset($metric['label'])?$metric['label']:'근거'); ?><br><strong><?php echo h(isset($metric['value'])&&$metric['value']!==null?(is_numeric($metric['value'])?number_format((float)$metric['value']):(string)$metric['value']).(isset($metric['unit'])?$metric['unit']:''):'-'); ?></strong></div><?php endforeach; ?></div><?php endif; ?><?php if(count($checks)>0): ?><h4>확인 권장사항</h4><ul><?php foreach($checks as $item): ?><li><?php echo h($item); ?></li><?php endforeach; ?></ul><?php endif; ?><?php if(count($limits)>0): ?><h4>자료 한계</h4><ul><?php foreach($limits as $item): ?><li><?php echo h($item); ?></li><?php endforeach; ?></ul><?php endif; ?></details></td></tr><?php endforeach; endif; ?></tbody></table></div><?php if($qhPages>1): ?><div class="qh-pages"><?php if($qhPage>1): ?><a class="qh-btn" href="<?php echo h(cpms_qh_url($qhPage-1,$qhFilters)); ?>">이전</a><?php endif; ?><strong><?php echo $qhPage; ?> / <?php echo $qhPages; ?></strong><?php if($qhPage<$qhPages): ?><a class="qh-btn" href="<?php echo h(cpms_qh_url($qhPage+1,$qhFilters)); ?>">다음</a><?php endif; ?></div><?php endif; ?></section></div>
